/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

void d2d_switch_port_tx(void *port, UInt8 code)
{
    UInt8 which_port;
    which_port = ((SmsgPort *)port)->number;

     if(which_port == UART_PORT0)
         U0THR = (UInt8) code;
     else if(which_port == UART_PORT1)
         U1THR = (UInt8) code;
     else if(which_port == UART_PORT3)
         U3THR = (UInt8) code;
}

